from lib import *
import b1_topics
italics.LV_ASCII |= b1_topics.LV_WORDS
B = dict(mcq_b=3, text_b=4, match_b=3)
_SET = iter(["At home", "At work", "In a shop", "At school", "In a café", "On a trip", "In a text", "In an email", "On the phone", "At a party", "In a letter", "On the news", "In a report", "At the doctor's", "In a lesson", "At the station", "In a chat", "In an exam", "At a hotel", "In a diary", "At the gym", "In a book", "At the bank", "In a hotel", "On a bus"])
def S(): return next(_SET) + ": "
def mk(name, en, lv, men=None, mlv=None):
    m = (men or en, mlv or lv)
    return Topic(name, **B, order=(en, lv), bank=(en, lv), gap=(en, lv), text=(en, lv), mcq=(en, lv), match=m)

# ============ Adjective order (B1.1 / B1.2) ============
P = mk("Adjective order (a small old car)",
    "Opinion, size, age, shape, colour, origin, material, then the noun: *a lovely small old round red Italian wooden table*.",
    "Viedoklis, izmērs, vecums, forma, krāsa, izcelsme, materiāls, tad lietvārds: *a lovely small old round red Italian wooden table*.")
for s, l in [("she bought a beautiful small black bag", "B1.1"), ("he lives in a big old house", "B1.1"), ("we stayed in a lovely small hotel", "B1.1"), ("i love my new red coat", "B1.1"), ("they have a small white dog", "B1.1"),
             ("she wore a long red silk dress", "B1.2"), ("he drives a big old german car", "B1.2"), ("i found a lovely little wooden box", "B1.2"), ("they live in a beautiful old stone cottage", "B1.2")]:
    P.order(l, s)
P.bank("B1.1", "She has a ___ small bag.", "beautiful", ["leather", "black"])
P.bank("B1.1", "She lives in a ___ old house.", "lovely", ["stone", "red"])
P.bank("B1.1", "We stayed in a small ___ hotel.", "old", ["lovely", "comfortable"])
P.bank("B1.1", "He bought a big ___ German car.", "red", ["lovely", "wooden"])
P.bank("B1.2", "They live in a ___ ___ stone cottage.", ["beautiful", "old"], ["wooden"])
P.bank("B1.2", "He drives a ___ ___ car.", ["big", "red"], ["wooden"])
P.bank("B1.2", "She wore a ___ cotton dress.", "lovely", ["white", "long"])
P.gap("B1.1", "We bought a ___ table. (round / wooden / lovely)", "lovely round wooden")
P.gap("B1.1", "He has a ___ car. (German / old / big)", "big old German")
P.gap("B1.1", "She wore a ___ dress. (silk / red / long)", "long red silk")
P.gap("B1.2", "I found a ___ box. (little / wooden / beautiful)", "beautiful little wooden")
P.gap("B1.2", "They live in a ___ house. (stone / old / lovely)", "lovely old stone")
P.gap("B1.2", "He wore a ___ jacket. (leather / brown / old)", "old brown leather")
P.mcq("B1.1", S() + "which sentence is correct?", "She has a beautiful small house.", ["She has a small beautiful house.", "She has a house beautiful small.", "She has a beautiful house small."])
P.mcq("B1.1", S() + "which sentence is NOT correct?", "He bought a leather black bag.", ["He bought a black leather bag.", "He bought a small black bag.", "He bought a lovely black bag."], b=4)
P.mcq("B1.1", "Choose the correct option: We stayed in a ___ hotel.", "lovely small", ["small lovely", "lovely smalls", "smalls lovely"])
P.mcq("B1.1", "Choose the correct option: She wore a ___ dress.", "long red", ["red long", "long reds", "reds long"])
P.mcq("B1.1", S() + "which sentence is correct?", "I live in an old stone house.", ["I live in a stone old house.", "I live in an stone old house.", "I live in old stone a house."])
P.mcq("B1.1", S() + "which sentence is correct?", "She has two small boxes.", ["She has two smalls boxes.", "She has two boxes smalls.", "She has two small box."])
P.mcq("B1.2", S() + "which sentence is NOT correct?", "She has a wooden round table.", ["She has a round wooden table.", "She has a lovely round table.", "She has a lovely wooden table."], b=4)
P.mcq("B1.2", "Choose the correct option: They bought a ___ car.", "big old German", ["German big old", "old big German", "big German old"])
P.mcq("B1.2", S() + "which sentence is correct?", "He wore a nice old brown jacket.", ["He wore a brown old nice jacket.", "He wore an old nice brown jacket.", "He wore a nice brown old jacket."])
P.mcq("B1.2", S() + "which sentence is NOT correct?", "We ate in an Italian small restaurant.", ["We ate in a small Italian restaurant.", "We ate in a lovely Italian restaurant.", "We ate in a lovely small restaurant."], b=4)
P.text("B1.1", "Correct the mistake: She bought a black small bag.", ["She bought a small black bag."])
P.text("B1.1", "Correct the mistake: He lives in an old big house.", ["He lives in a big old house."])
P.text("B1.1", "Write the phrase with the words in the right order: a, house, lovely, old", ["a lovely old house"])
P.text("B1.2", "Correct the mistake: She wore a silk red long dress.", ["She wore a long red silk dress."])
P.text("B1.2", "Correct the mistake: They bought a wooden round beautiful table.", ["They bought a beautiful round wooden table."])
P.text("B1.2", "Write the phrase with the words in the right order: a, box, wooden, small, lovely", ["a lovely small wooden box"])
P.match("B1.1", "Match each adjective with its kind.", [("beautiful", "opinion"), ("small", "size"), ("old", "age"), ("red", "colour")])
P.match("B1.2", "Match each word with its kind.", [("round", "shape"), ("Spanish", "origin"), ("silk", "material"), ("huge", "size")])
P.match("B1.2", "Match each wrong phrase with its correct version.", [("a red big car", "a big red car"), ("an old lovely house", "a lovely old house"), ("a wooden small box", "a small wooden box"), ("a French old film", "an old French film")])

# ============ Adverbs: manner, frequency, degree (A2.2 / B1.1 / B1.2) ============
P = mk("Adverbs: manner, frequency, degree",
    "Manner: *-ly* (*carefully*, but *well, fast, hard*). Frequency: *always, never* go before the verb, after *be*. Degree: *very, quite, too, enough*.",
    "Veids: *-ly* (*carefully*, bet *well, fast, hard*). Biežums: *always, never* ir pirms darbības vārda, aiz *be*. Pakāpe: *very, quite, too, enough*.")
for s, l in [("she speaks english very well", "A2.2"), ("he always arrives late", "A2.2"), ("they walked slowly to the station", "A2.2"),
             ("i can hardly hear you", "B1.1"), ("we rarely eat out on weekdays", "B1.1"), ("he has never been to london", "B1.1"),
             ("the test was surprisingly easy", "B1.2"), ("she plays the piano extremely well", "B1.2"), ("they have almost finished the project", "B1.2")]:
    P.order(l, s)
P.order("B1.1", "she carefully closed the door", also=["she closed the door carefully"])
P.bank("A2.2", "She sings ___.", "beautifully", ["beautiful", "beauty"])
