P.gap("B1.2", "He is learning quickly. He ___ speaks Spanish now.", "almost | nearly | already")
P.mcq("A2.2", S() + "which sentence is correct?", "She speaks English well.", ["She speaks English good.", "She speaks well English.", "She well speaks English."])
P.mcq("A2.2", S() + "which sentence is NOT correct?", "He late always arrives.", ["He always arrives late.", "He often arrives late.", "He is always late."], b=4)
P.mcq("A2.2", "Choose the correct option: She looks ___ today.", "happy", ["happily", "happiness", "happies"])
P.mcq("A2.2", "Choose the correct option: He answered the question ___.", "correctly", ["correct", "correction", "corrects"])
P.mcq("A2.2", "Choose the correct option: He drives very ___.", "carefully", ["careful", "care", "carefuly"])
P.mcq("B1.1", "Choose the correct option: I ___ see you. The room is too dark.", "can hardly", ["can hard", "hardly can", "hard can"])
P.mcq("B1.1", S() + "which sentence is correct?", "He works hard every day.", ["He works hardly every day.", "He hard works every day.", "He works hards every day."])
P.mcq("B1.1", S() + "which sentence is correct?", "She never drinks coffee.", ["She drinks never coffee.", "She never does drinks coffee.", "She drinks coffee never."])
P.mcq("B1.2", "Choose the correct option: The soup wasn't hot ___ to eat.", "enough", ["too", "very", "so"])
P.mcq("B1.2", "Choose the correct option: She works so ___ that she is always tired.", "hard", ["hardly", "harder", "hards"])
P.mcq("B1.2", S() + "which sentence is correct?", "She carefully opened the box.", ["She carefully the box opened.", "She opened the box carefulness.", "She careful opened the box."])
P.mcq("B1.2", S() + "which sentence is NOT correct?", "He speaks Spanish fluent.", ["He speaks Spanish fluently.", "He speaks fluent Spanish.", "He speaks Spanish very fluently."], b=4)
