# ============ So and such (B1.1 / B1.2) ============
P = mk("So and such",
    "*so* + adjective / adverb: *so tired*. *such* + (*a*) + (adjective) + noun: *such a long film*. *so much / so many* + noun. Result: *so / such ... that*.",
    "*so* + īpašības vārds / apstākļa vārds: *so tired*. *such* + (*a*) + (īpašības vārds) + lietvārds: *such a long film*. *so much / so many* + lietvārds. Sekas: *so / such ... that*.")
for s, l in [("it was such a long film", "B1.1"), ("she is so tired", "B1.1"), ("he was so late that we left", "B1.1"), ("they are such nice people", "B1.1"),
             ("it was such a cold day that we stayed in", "B1.2"), ("there were so many people that we couldn't move", "B1.2"), ("she was so angry that she left the room", "B1.2"), ("it was such terrible weather that the flight was cancelled", "B1.2")]:
    P.order(l, s)
P.bank("B1.1", "The film was ___ long.", "so", ["such", "such a"])
P.bank("B1.1", "It was ___ a long film.", "such", ["so", "very"])
P.bank("B1.1", "They are ___ nice people.", "such", ["so", "a"])
P.bank("B1.1", "She was ___ tired that she fell asleep at once.", "so", ["such", "too"])
P.bank("B1.2", "There was ___ much noise that I couldn't sleep.", "so", ["such", "very"])
P.bank("B1.2", "It was ___ terrible weather that we stayed in.", "such", ["so", "a"])
P.bank("B1.2", "He is ___ a good teacher.", "such", ["so", "very"])
P.gap("B1.1", "I was ___ hungry that I ate everything.", "so")
P.gap("B1.1", "It was ___ an interesting book that I read it twice.", "such")
P.gap("B1.1", "I've never seen ___ a big dog.", "such")
P.gap("B1.2", "There were ___ many people that we couldn't get in.", "so")
P.gap("B1.2", "They were ___ kind people that everyone loved them.", "such")
P.gap("B1.2", "I was ___ surprised that I couldn't speak.", "so")
P.mcq("B1.1", S() + "which sentence is correct?", "It was such a long film.", ["It was so a long film.", "It was such long film.", "It was so long film."])
P.mcq("B1.1", S() + "which sentence is NOT correct?", "She is such tired.", ["She is so tired.", "She is such a tired child.", "She is very tired."], b=4)
P.mcq("B1.1", "Choose the correct option: They are ___ nice people.", "such", ["so", "such a", "so a"])
P.mcq("B1.1", "Choose the correct option: I was ___ tired that I fell asleep.", "so", ["such", "such a", "too"])
P.mcq("B1.1", "Choose the correct option: It was ___ a surprise.", "such", ["so", "very", "so a"])
P.mcq("B1.2", "Choose the correct option: There were ___ people that we couldn't move.", "so many", ["such many", "so much", "such a many"])
P.mcq("B1.2", S() + "which sentence is correct?", "It was such terrible weather that we stayed in.", ["It was so terrible weather that we stayed in.", "It was such a terrible weather that we stayed in.", "It was so a terrible weather that we stayed in."])
P.mcq("B1.2", S() + "which sentence is NOT correct?", "She has such much work.", ["She has so much work.", "She has such a lot of work.", "She has so many tasks."], b=4)
P.mcq("B1.2", "Choose the correct option: He drove ___ fast that we were afraid.", "so", ["such", "such a", "very"])
P.mcq("B1.2", S() + "which sentence is correct?", "The room was so dark that I couldn't see anything.", ["The room was such dark that I couldn't see anything.", "The room was such a dark that I couldn't see anything.", "The room was so a dark that I couldn't see anything."])
P.text("B1.1", "Rewrite with so: It was very cold. We stayed inside.", ["It was so cold that we stayed inside."])
P.text("B1.1", "Correct the mistake: It was such cold that we stayed inside.", ["It was so cold that we stayed inside.", "It was such cold weather that we stayed inside."])
