P.mcq("A2.2", S() + "which sentence is NOT correct?", "She didn't say nothing.", ["She didn't say anything.", "She said nothing.", "She said something."], b=4)
P.mcq("A2.2", "Choose the correct option: There isn't ___ at home.", "anyone", ["no one", "nobody", "nothing"])
P.mcq("A2.2", "Choose the correct option: I can't find my phone ___.", "anywhere", ["nowhere", "none", "some"])
