P.mcq("B1.1", "Choose the correct option: Would you like ___ to drink?", "something", ["some", "any", "every"])
P.mcq("B1.1", "Choose the correct option: Everybody ___ here. Let's start.", "is", ["are", "am", "be"])
P.mcq("B1.1", S() + "which sentence is correct?", "Nobody has called me.", ["Nobody have called me.", "Nobody has not called me.", "Nobody didn't call me."])
P.mcq("B1.1", S() + "which sentence is NOT correct?", "Everyone have finished.", ["Everyone has finished.", "Everyone did their best.", "Everybody is ready."], b=4)
P.mcq("B1.1", S() + "which sentence is correct?", "She said nothing to anyone.", ["She said nothing to no one.", "She didn't say nothing to anyone.", "She said anything to nobody."])
